type ReleaseNotesProps = { open: boolean; onClose: () => void };

export function ReleaseNotes({ open, onClose }: ReleaseNotesProps) {
  const t = useTranslate();
  if (!open) return null;
  return <div className="notes-layer" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}>
    <aside className="notes-drawer" role="dialog" aria-modal="true" aria-label="UPDATE LOG">
      <header className="notes-header"><div><span className="eyebrow">CHANGELOG / 小小CSGO</span><h2>{t('notes.title')}</h2></div><button className="notes-close" aria-label="CLOSE UPDATE LOG" title="Close update log" onClick={onClose}><X size={18} /></button></header>
      <div className="notes-list">{releases.map((release) => <article className={`release ${release.current ? 'current' : ''}`} key={release.version}><div className="release-meta"><strong>{release.version}</strong><span>{release.date}</span>{release.current && <em>CURRENT</em>}</div><h3>{release.title}</h3><ul>{release.items.map((item) => <li key={item}>{item}</li>)}</ul></article>)}</div>
      <footer className="notes-footer">{t('notes.footer')}</footer>
    </aside>
  </div>;
}
